#!/bin/bash

echo "🚀 Starting Local Development Environment"
echo ""

# Kill existing processes
pkill -f "netlify dev" 2>/dev/null
pkill -f "yarn start" 2>/dev/null
sleep 2

# Start React dev server in background
echo "📦 Starting React dev server on port 3000..."
cd frontend
PORT=3000 yarn start > /tmp/react-dev.log 2>&1 &
REACT_PID=$!
cd ..
echo "   ✅ React server started (PID: $REACT_PID)"
echo ""

# Wait for React to start
echo "⏳ Waiting for React server to initialize..."
sleep 15

# Start Netlify Dev to proxy and provide functions
echo "🔧 Starting Netlify Dev on port 8888..."
# Use --live flag to keep it running and proxy to React
netlify dev --port 8888 --live > /tmp/netlify-dev.log 2>&1 &
NETLIFY_PID=$!
echo "   ✅ Netlify Dev started (PID: $NETLIFY_PID)"
echo ""

sleep 10

